INSERT INTO "cluster_profiles" ("cluster_id", "cluster_name", "description", "score_min", "score_max") VALUES (1, 'The Traditionalist', 'AI is not yet a topic of discussion. Operations are predominantly manual, data is siloed or analog, and there is often significant cultural skepticism.', 1.0, 1.5);
INSERT INTO "cluster_profiles" ("cluster_id", "cluster_name", "description", "score_min", "score_max") VALUES (2, 'The Experimental Explorer', 'The organization has started "playing" with AI through isolated tools like ChatGPT. There is curiosity but no formal strategy or oversight.', 1.6, 2.5);
INSERT INTO "cluster_profiles" ("cluster_id", "cluster_name", "description", "score_min", "score_max") VALUES (3, 'The Structured Builder', 'A solid technical and strategic foundation is being laid. High-level roadmaps and cloud infrastructure are in place, but scaling remains difficult.', 2.6, 3.5);
INSERT INTO "cluster_profiles" ("cluster_id", "cluster_name", "description", "score_min", "score_max") VALUES (4, 'The Operational Scaler', 'AI is delivering measurable ROI. Leadership is aligned, and the organization is moving multiple use cases into production.', 3.6, 4.5);
INSERT INTO "cluster_profiles" ("cluster_id", "cluster_name", "description", "score_min", "score_max") VALUES (5, 'The AI-Driven Leader', 'AI is a core strategic pillar. The workforce is highly literate, data flows are automated, and the company sets industry standards.', 4.6, 5.0);
