INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (52, 10, 'ERP System - ', 4, 11.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (67, 13, 'Minimal / Unsure - We do not have a formal feasibility check; projects are often started based on excitement or intuition without verifying data or compliance requirements first.', 1, 1.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (68, 13, 'Reactive Assessment - We perform basic checks only after a project has started, often leading to delays or "stuck" projects when data or legal issues unexpectedly emerge.', 2, 2.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (69, 13, 'Basic Due Diligence - We have an informal "Pre-Check" for major projects where we verify if the necessary data exists and if there are obvious legal hurdles.', 3, 3.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (70, 13, 'Structured Validation - We use a clear "Go/No-Go" process for every use case that validates data readiness, process alignment, and regulatory compliance before any budget is released.', 4, 4.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (71, 13, 'Optimized Strategic Filtering - We use a standardized, data-driven validation engine that ensures every initiative is perfectly aligned with business goals, technical capabilities, and compliance standards from the start.', 5, 5.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (92, 18, 'Undefined / Ad-hoc - We do not have a set process for AI projects; tasks are handled as they arise without formal planning or clear ownership.', 1, 1.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (93, 18, 'Individual Initiative - Project delivery depends on the effort of specific individuals; while some projects succeed, we lack a repeatable "playbook" for the whole team.', 2, 2.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (94, 18, 'Basic Standardization - We use a consistent workflow (e.g., simple task tracking or weekly sprints) that allows us to manage AI projects with predictable timelines.', 3, 3.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (95, 18, 'Targeted & Results-Oriented - We use a process specifically adapted for AI (e.g., early prototyping and data-readiness checks), ensuring we don''t waste resources on unfeasible ideas.', 4, 4.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (96, 18, 'High-Velocity Delivery - Our implementation engine is highly efficient; we can rapidly move from a "Proof of Concept" to a live tool with minimal friction and clear ROI tracking.', 5, 5.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (143, 28, 'External Pressure - We are responding to external hype or competitor moves without a clear internal goal.', 1, 0.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (144, 28, 'Resource Optimization - We want to identify where AI can reduce costs or automate repetitive manual tasks.', 2, 0.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (145, 28, 'Strategic Clarity - We need a professional roadmap to align AI initiatives with our core business objectives.', 3, 0.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (146, 28, ' Readiness Check - We aim to evaluate our technical infrastructure and workforce skills for upcoming scaling.', 4, 0.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (147, 28, 'Competitive Advantage - We are seeking to define a market-leading position through high-impact AI innovation.', 5, 0.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (156, 30, 'No Impact - We have not assessed AI trends and have no documented strategy regarding them.', 1, 0.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (157, 30, 'Reactive - We acknowledge the trend but only respond to external pressures on an ad-hoc basis.', 2, 0.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (158, 30, 'Exploratory - We monitor trends and have initiated pilot projects to address specific needs.', 3, 0.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (159, 30, 'Strategic - AI is a key planning driver with a formal roadmap for systematic integration.', 4, 0.0);
INSERT INTO "answers" ("answer_id", "question_id", "answer_text", "answer_level", "answer_weight") VALUES (160, 30, 'Innovative - We leverage AI to redefine our business model and set industry standards.', 5, 0.0);
